import{_ as n,I as i,c as s,o as r,ag as e,J as o}from"./chunks/framework.Vyheyqg9.js";const b=JSON.parse('{"title":"EC2, load balancing and scaling","description":"","frontmatter":{},"headers":[],"relativePath":"aws/compute-and-scaling.md","filePath":"aws/compute-and-scaling.md"}'),c={name:"aws/compute-and-scaling.md"};function l(d,a,p,h,u,m){const t=i("MermaidDiagram");return r(),s("div",null,[a[0]||(a[0]=e('<h1 id="ec2-load-balancing-and-scaling" tabindex="-1">EC2, load balancing and scaling <a class="header-anchor" href="#ec2-load-balancing-and-scaling" aria-label="Permalink to “EC2, load balancing and scaling”">​</a></h1><p>EC2 provides virtual machines. Compared with Lambda, it gives you more control over the operating system and long-running processes, while assigning you more maintenance work.</p><h2 id="the-instance-building-blocks" tabindex="-1"><span class="hub-section-number">1 </span>The instance building blocks <a class="header-anchor" href="#the-instance-building-blocks" aria-label="Permalink to “1 The instance building blocks”">​</a></h2><p>An instance type determines a balance of CPU, memory, networking and storage capability. An AMI supplies an operating-system image and initial software. EBS provides attached block storage; instance-store storage is tied to instance lifecycle and should not be treated as durable database storage. <a href="https://docs.aws.amazon.com/AWSEC2/latest/UserGuide/concepts.html" target="_blank" rel="noreferrer">EC2 overview</a>.</p><p>A launch template records instance configuration for repeatable launches. User data can initialize an instance, often through cloud-init. Initialization failure requires inspecting boot and cloud-init logs; an instance being “running” does not prove the application started successfully.</p><p>Instance metadata provides instance context and access to instance-role credentials through supported mechanisms. Protect metadata access and use IMDSv2 as appropriate. Never expose a proxy endpoint that allows untrusted callers to retrieve metadata credentials. <a href="https://docs.aws.amazon.com/AWSEC2/latest/UserGuide/configuring-instance-metadata-service.html" target="_blank" rel="noreferrer">Instance metadata</a>.</p><h2 id="capacity-and-purchasing-choices" tabindex="-1"><span class="hub-section-number">2 </span>Capacity and purchasing choices <a class="header-anchor" href="#capacity-and-purchasing-choices" aria-label="Permalink to “2 Capacity and purchasing choices”">​</a></h2><table tabindex="0"><thead><tr><th>Choice</th><th>Main consideration</th></tr></thead><tbody><tr><td>On-Demand</td><td>Flexible usage without a long-term purchasing commitment</td></tr><tr><td>Spot</td><td>Interruption-tolerant work using spare capacity</td></tr><tr><td>Savings Plans / Reserved Instances</td><td>Discounts associated with commitment and applicable conditions</td></tr><tr><td>Burstable instance families</td><td>CPU-credit behavior affects sustained workload suitability</td></tr></tbody></table><p>A discount model is not an availability strategy. Spot workers need interruption handling and recoverable work. Persistent services need more than a low hourly price.</p><h2 id="load-balancing-and-auto-scaling" tabindex="-1"><span class="hub-section-number">3 </span>Load balancing and Auto Scaling <a class="header-anchor" href="#load-balancing-and-auto-scaling" aria-label="Permalink to “3 Load balancing and Auto Scaling”">​</a></h2>',10)),o(t,{"encoded-source":"flowchart%20LR%0A%20%20%20%20Client%5BClient%5D%20--%3E%20LB%5BLoad%20balancer%5D%0A%20%20%20%20LB%20--%3E%20A%5BHealthy%20instance%20in%20AZ%20A%5D%0A%20%20%20%20LB%20--%3E%20B%5BHealthy%20instance%20in%20AZ%20B%5D%0A%20%20%20%20ASG%5BAuto%20Scaling%20group%5D%20-.%20Maintains%20desired%20capacity%20.-%3E%20A%0A%20%20%20%20ASG%20-.%20Maintains%20desired%20capacity%20.-%3E%20B"}),a[1]||(a[1]=e('<p>A listener receives traffic. Rules select a target group, and health checks determine eligible targets. Application Load Balancers suit HTTP routing features; Network Load Balancers suit transport-level requirements. Choose based on protocol and behavior, not only the service name.</p><p>Auto Scaling maintains a desired instance count within configured bounds and can adjust it using policies. New instances need startup time. Scaling cannot instantly absorb every spike, and distributing traffic does not fix a saturated shared database.</p><p>Keep application state outside replaceable instances where needed. An uploaded file on one instance&#39;s local disk will not automatically appear on another instance. An in-memory login session can disappear when an instance is replaced.</p><h2 id="availability-is-a-system-property" tabindex="-1"><span class="hub-section-number">4 </span>Availability is a system property <a class="header-anchor" href="#availability-is-a-system-property" aria-label="Permalink to “4 Availability is a system property”">​</a></h2><p>Multiple instances in one AZ do not protect against that AZ becoming unavailable. Multiple AZs do not protect against every bad deployment or accidental database deletion. A useful design combines appropriate redundancy with health checks, recoverable state and a release strategy.</p><p>SSH access requires network reachability and operating-system credentials. IAM permissions alone do not log you into the OS. Systems Manager Session Manager can provide managed access when its prerequisites are configured; a bastion is another design with its own maintenance and access controls.</p><h2 id="observe-what-is-actually-measured" tabindex="-1"><span class="hub-section-number">5 </span>Observe what is actually measured <a class="header-anchor" href="#observe-what-is-actually-measured" aria-label="Permalink to “5 Observe what is actually measured”">​</a></h2><p>Default EC2 metrics do not automatically expose every guest operating-system metric. Memory and filesystem details often require an agent or custom telemetry. Track service health, application latency and errors alongside host utilization.</p><p>Use <a href="./networking.html">VPC networking</a> to understand why a healthy instance may still be unreachable, and <a href="./delivery-and-operations.html">delivery</a> for release and recovery behavior.</p>',9))])}const y=n(c,[["render",l]]);export{b as __pageData,y as default};
